import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Color,
  } = THREE;

  const root = new Group();
  root.name = config.id || 'journal-quote-panel';

  const resources = [];
  const primitiveResults = [];
  const timelines = [];
  let disposed = false;

  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const makeBasic = (color, opacity = 1, transparent = false) => {
    const material = new MeshBasicNodeMaterial({
      color,
      transparent,
      opacity,
      depthWrite: opacity >= 1,
    });
    resources.push(material);
    return material;
  };

  const makePlane = (width, height, material, z = 0) => {
    const mesh = new Mesh(new PlaneGeometry(width, height), material);
    mesh.position.z = z;
    resources.push(mesh.geometry);
    return mesh;
  };

  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, uv().y),
  );
  resources.push(backdropMaterial);

  const backdrop = makePlane(7, 6, backdropMaterial, -2.5);
  backdrop.name = 'designed-dark-stage';
  root.add(backdrop);

  const vignette = makeBasic(colors.ink, 0.28, true);
  const vignettePlane = makePlane(6.9, 5.9, vignette, -2.42);
  root.add(vignettePlane);

  const shadowMaterial = makeBasic(colors.surface, 0.52, true);
  const shadow = makePlane(3.9, 2.35, shadowMaterial, -0.12);
  shadow.scale.set(1.12, 0.32, 1);
  shadow.name = 'contact-shadow';
  root.add(shadow);

  const card = new Group();
  card.name = 'quote-card';
  root.add(card);

  const imageMaterial = makeBasic(colors.paper);
  imageMaterial.transparent = true;
  imageMaterial.opacity = 0.92;
  imageMaterial.depthWrite = true;

  const imagePlane = makePlane(3.45, 2.15, imageMaterial, 0);
  imagePlane.name = 'quote-panel-image';
  card.add(imagePlane);

  const surfaceOverlay = makeBasic(colors.surface, 0.42, true);
  const overlayPlane = makePlane(3.43, 2.13, surfaceOverlay, 0.025);
  overlayPlane.name = 'surface-overlay';
  card.add(overlayPlane);

  const innerPaper = makeBasic(colors.paper, 0.34, true);
  const innerTop = makePlane(2.95, 0.018, innerPaper, 0.055);
  innerTop.position.y = 0.91;
  card.add(innerTop);

  const accentMaterial = makeBasic(colors.accent, 1);
  const accentEdge = makePlane(0.045, 1.95, accentMaterial, 0.07);
  accentEdge.position.x = -1.62;
  accentEdge.name = 'accent-edge';
  accentEdge.visible = false;
  card.add(accentEdge);

  const accentMarker = makePlane(0.34, 0.045, accentMaterial, 0.07);
  accentMarker.position.set(-1.42, 0.91, 0);
  accentMarker.name = 'accent-marker';
  card.add(accentMarker);

  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  let textY = 0.42;
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const role = item.role || 'body';
    const size =
      item.typography?.fontSize ??
      (role === 'headline' ? 0.34 :
        role === 'subhead' ? 0.2 :
          role === 'caption' ? 0.09 : 0.13);

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: size,
      color: role === 'caption' ? colors.accent : colors.paper,
      align: 'left',
      maxWidthPx: 920,
      letterSpacingPx: role === 'caption' ? size * 0.08 : 0,
    });

    textObject.position.set(-1.25, textY, 0.09);
    textObject.name = `quote-text-${role}`;
    card.add(textObject);
    textY -= role === 'headline' ? 0.48 : 0.27;
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      if ('colorSpace' in texture && THREE.SRGBColorSpace) {
        texture.colorSpace = THREE.SRGBColorSpace;
      }
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      resources.push(texture);
    });
  }

  const settle = gsap.timeline({ paused: true });
  settle
    .fromTo(
      card.scale,
      { x: 1.04, y: 1.04, z: 1.04 },
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    )
    .fromTo(
      card.position,
      { y: 0.4 },
      { y: 0, duration: 0.7, ease: 'power3.out' },
      0,
    );
  timelines.push(settle);
  settle.play();

  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(card.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power2.out',
  });
  timelines.push(hoverTimeline);

  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline
    .to(card.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out',
    })
    .to(card.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.28,
      ease: 'back.out(1.7)',
    });
  timelines.push(pressTimeline);

  const primitiveSpecs = config.cinematicPrimitives || [];
  for (const primitive of primitiveSpecs) {
    if (!primitive?.name || typeof ctx.primitives?.[primitive.name] !== 'function') {
      continue;
    }
    const result = ctx.primitives[primitive.name](root, primitive.params || {});
    if (result) primitiveResults.push(result);
  }

  root.userData.handlers = {
    hover(active = true) {
      if (disposed) return;
      if (active) hoverTimeline.play();
      else hoverTimeline.reverse();
    },

    click() {
      if (disposed) return;
      pressTimeline.restart();
      ctx.emit('hub-journal.select', {
        nodeId: config.id || 'journal-quote-panel',
      });
    },

    focus(active = true) {
      if (disposed) return;
      accentEdge.visible = !!active;
    },
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) timeline.kill();
    for (const result of primitiveResults) result?.cleanup?.();

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        for (const material of materials) material.dispose?.();
      }
    });

    for (const resource of resources) {
      if (resource?.dispose && resource !== imageMaterial) resource.dispose();
    }
  };

  return root;
}
